Console.WriteLine("=== ALL PROJECTS ===");
foreach (var p in projects)
{
    Console.WriteLine($"  {p.Name} - Succeeded: {p.Succeeded}");
}

Console.WriteLine("\n=== ALL ERRORS (grouped by project) ===");
var grouped = errors.GroupBy(e => e.GetNearestParent<Project>()?.Name ?? "unknown");
foreach (var g in grouped)
{
    Console.WriteLine($"\n--- {g.Key} ---");
    foreach (var e in g)
    {
        Console.WriteLine($"  {e.File}({e.LineNumber},{e.ColumnNumber}): error {e.Code}: {e.Text}");
    }
}

// Check for dependency failures
Console.WriteLine("\n=== PROJECT REFERENCES (from targets) ===");
var items = build.FindChildrenRecursive<Item>();
foreach (var item in items.Where(i => i.Name == "ProjectReference").Take(20))
{
    var proj = item.GetNearestParent<Project>()?.Name ?? "?";
    Console.WriteLine($"  [{proj}] -> {item.Text}");
}
EOF
