using System;
using System.Linq;
using Microsoft.Build.Logging.StructuredLogger;

var build = BinaryLog.ReadBuild("build.binlog");

// Get source files from the binlog
Console.WriteLine("=== SOURCE FILES IN Services.csproj ===");
var sourceFiles = build.FindChildrenRecursive<Item>()
    .Where(i => i.Name == "Compile" || i.Name == "Content" || i.Name == "None")
    .Select(i => i.Text)
    .Where(t => t.Contains("Services"))
    .Distinct()
    .ToList();
foreach (var f in sourceFiles) Console.WriteLine($"  {f}");

// Look for the actual source content in messages
Console.WriteLine("\n=== MESSAGES ABOUT PACKAGES (Services) ===");
var msgs = build.FindChildrenRecursive<Message>()
    .Where(m => m.Text != null && (m.Text.Contains("Newtonsoft") || m.Text.Contains("PackageReference")))
    .Take(20);
foreach (var m in msgs)
{
    var proj = m.GetNearestParent<Project>()?.Name ?? "?";
    Console.WriteLine($"  [{proj}] {m.Text.Substring(0, Math.Min(200, m.Text.Length))}");
}

// Look at Api.csproj build result
Console.WriteLine("\n=== Api.csproj ERRORS ===");
var apiErrors = build.FindChildrenRecursive<Error>()
    .Where(e => e.GetNearestParent<Project>()?.Name == "Api.csproj");
foreach (var e in apiErrors)
    Console.WriteLine($"  {e.Code}: {e.Text}");
if (!apiErrors.Any())
    Console.WriteLine("  (none - but may have failed due to dependency on Services.csproj)");

// Check if Api depends on Services
Console.WriteLine("\n=== BUILD MESSAGES about project failure ===");
var failMsgs = build.FindChildrenRecursive<Message>()
    .Where(m => m.Text != null && (m.Text.Contains("failed") || m.Text.Contains("not build")))
    .Take(10);
foreach (var m in failMsgs)
    Console.WriteLine($"  {m.Text.Substring(0, Math.Min(300, m.Text.Length))}");
EOF
